        if isinstance(d, dict):
            return d.get(k, default)
    except Exception:
        return default
    return default

def low(x):
    return str(x or '').lower()

def needverb(tt):
    t = low(tt)
    if 'cool' in t:
        return 'cool'
    if 'heat' in t:
        return 'heat'
    return 'clean'

def hasact(adm, prefix, target, extra):
    for a in adm or []:
        s = ' ' + low(a) + ' '
        if s.startswith(' ' + prefix + ' ') and (not target or target in s) and (not extra or extra in s):
            return True
    return False

def hook(ctx, nb):
    task = ctx.get('task') or {}
    world = ctx.get('world') or {}
    tt = getv(task, 'task_type', '')
    target = low(getv(task, 'target_type', ''))
    dest = low(getv(task, 'destination_type', ''))
    verb = needverb(tt)
    adm = ctx.get('admissible') or []
    act = low(getv(ctx.get('action'), 'final_action', getv(ctx.get('action'), 'normalized', getv(ctx.get('action'), 'raw', '')))).strip()
    obs = low(ctx.get('observation') or '')
    need = ''
    if 'heat' in tt:
        need = 'heat'
    if 'cool' in tt:
        need = 'cool'
    if 'clean' in tt:
        need = 'clean'
    if need and act.startswith(need + ' ') and target and target in act and ('you ' + need in obs or 'now ' + need in obs):
        nb['transformed'] = True
    inv = low(world.get('inventory', ''))
    inv_non = bool(inv and 'nothing' not in inv and 'empty' not in inv and 'not carrying' not in inv)
    inv_target = bool(inv_non and target and target in inv)
    carrying_target = bool(nb.get('carrying_target') or inv_target)
    if not inv_non and not inv_target:
        carrying_target = False
    pc = world.get('placed_count')
    try:
        pc = int(pc or 0)
    except Exception:
        pc = 0
    if pc > nb.get('placed_count', 0):
        nb['placed_count'] = pc
    locs = world.get('placed_locations') or []
    slots = 2 if 'two' in tt else 1
    if isinstance(locs, str) and locs not in nb.get('placed_locations', []):
        if not nb.get('placed_locations'):
            nb['placed_locations'] = []
        nb['placed_locations'].append(locs)
    if act.startswith('put ') and target and target in act and 'you put' in obs and (not dest or dest in act):
        if pc < nb.get('placed_count', 0) + 1:
            nb['placed_count'] = nb.get('placed_count', 0) + 1
    wrong = bool(inv_non and target and not inv_target)
    if wrong:
        nb['stage'] = 'wrong_inventory'
    elif nb.get('placed_count', 0) >= slots:
        nb['stage'] = 'done'
    elif carrying_target:
        if need and not nb.get('transformed') and need in act and not (act.startswith('put ') and target in act and (not dest or dest in act)):
            nb['stage'] = 'transform'
        elif hasact(adm, 'put ', target, dest):
            nb['stage'] = 'put_target'
        else:
            nb['stage'] = 'go_destination'
    else:
        if wrong:
            nb['stage'] = 'wrong_inventory'
        elif nb.get('placed_count', 0) > 0 and nb.get('placed_count', 0) < slots and target and act.startswith('take ') and target in act:
            nb['stage'] = 'wrong_inventory'
        elif hasact(adm, 'take ', target, '') and not (act.startswith('take ') and target and target in act and (not dest or dest in act)):
            nb['stage'] = 'take_target'
        else:
            nb['stage'] = 'find_target'
    if not wrong:
        nb['carrying_target'] = carrying_target
    return None

