def needverb(tt):
    t = low(tt or '')
    if 'cool' in t:
        return 'cool'
    if 'heat' in t:
        return 'heat'
    return 'clean'

def hook(ctx, nb):
    task = ctx.get('task') or {}
    tt = getv(task, 'task_type', '')
    target = low(getv(task, 'target_type', '')) or 'target'
    dest = low(getv(task, 'destination_type', '')) or 'destination'
    verb = needverb(tt)
    if not target or not tt:
        return None
    stage = nb.get('stage') or 'find_target'
    pred = ctx.get('predicates') or {}
    state = ctx.get('state') or {}
    rep = bool(getv(pred, 'same_action_repeated', False) or getv(pred, 'same_observation_repeated', False) or getv(pred, 'nothing_happens_repeated', False) or getv(state, 'repeated_action_count', 0) > 1 or getv(state, 'repeated_observation_count', 0) > 1)
    lowb = bool(getv(pred, 'remaining_steps_low', False) or getv(ctx.get('predicates'), 'remaining_steps_low', False))
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'You are carrying a non-target item. Do not place it as the goal object; recover and find a ' + target + '.'
    elif stage == 'take_target' and (rep or lowb):
        msg = 'A ' + target + ' is available here. Take the target now instead of continuing to search.'
    elif stage == 'transform' and verb:
        msg = 'You have the ' + target + '. Before placing it, ' + verb + ' it with the appropriate appliance or fixture.'
    elif stage == 'go_destination' and (rep or lowb):
        msg = 'Carry the ' + target + ' to a ' + dest + ' and do not put it in unrelated containers.'
    elif stage == 'put_target' and (rep or lowb):
        msg = 'You are at the destination. Put the ' + target + ' in/on the ' + dest + ' now.'
    if msg:
        key = stage + ':' + msg[:70]
        if nb.get('last_hint') == key:
            return None
        nb['last_hint'] = key
        return {'message': msg}
    return None

